CREATE TABLE IF NOT EXISTS categories (id text PRIMARY KEY, name text NOT NULL, emoji text NOT NULL, color text NOT NULL);
CREATE TABLE IF NOT EXISTS questions (id text PRIMARY KEY, prompt text NOT NULL, type text NOT NULL, category_id text NOT NULL REFERENCES categories(id), secondary_category_ids jsonb NOT NULL DEFAULT '[]', difficulty integer NOT NULL CHECK (difficulty BETWEEN 0 AND 10), options jsonb NOT NULL, correct_option_id text, correct_order jsonb, explanation text NOT NULL, source_label text, source_url text, tags jsonb NOT NULL DEFAULT '[]', origin text NOT NULL, status text NOT NULL, fingerprint text NOT NULL UNIQUE, quality_score integer NOT NULL, time_sensitive boolean NOT NULL DEFAULT false, valid_until timestamptz, model_id text, prompt_version text, validation_status text, play_count integer NOT NULL DEFAULT 0, correct_rate numeric NOT NULL DEFAULT 0, report_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS questions_category_difficulty_idx ON questions(category_id,difficulty,status);
